set +e
code(){ printf "%-48s %s\n" "$1" "$(curl -s -o /dev/null -m 15 -w '%{http_code}' -A 'palate-search-lab/1.0' "$1")"; }
echo "== reachability"; for u in https://fragrantica.com/ https://www.parfumo.com/ https://world.openbeautyfacts.org/ https://world.openfoodfacts.org/ https://www.thecocktaildb.com/api/json/v1/1/search.php?s=margarita https://www.themealdb.com/api/json/v1/1/search.php?s=arrabiata https://vpic.nhtsa.dot.gov/api/vehicles/GetModelsForMake/porsche?format=json https://www.fueleconomy.gov/feg/epadata/vehicles.csv.zip https://query.wikidata.org/sparql https://huggingface.co/api/datasets?search=fragrantica https://commons.wikimedia.org/ https://api.deezer.com/search/artist?q=bruno https://itunes.apple.com/search?term=jack+johnson https://graphql.anilist.co https://rawg.io/api/games https://api.igdb.com/v4/games https://www.googleapis.com/books/v1/volumes?q=dune https://openlibrary.org/search.json?q=dune; do code "$u"; done
echo; echo "== CORS headers (needed for browser calls)"; for u in "https://world.openbeautyfacts.org/cgi/search.pl?search_terms=dior&search_simple=1&action=process&json=1&page_size=1" "https://world.openfoodfacts.org/api/v2/search?page_size=1" "https://www.thecocktaildb.com/api/json/v1/1/search.php?s=margarita" "https://vpic.nhtsa.dot.gov/api/vehicles/GetModelsForMake/porsche?format=json" "https://query.wikidata.org/sparql?query=SELECT%201&format=json" "https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&titles=File:Example.jpg"; do printf "%s\n   " "$u"; curl -s -D - -o /dev/null -m 20 -H 'Origin: https://trypalate.github.io' -A 'palate-search-lab/1.0' "$u" | grep -i '^access-control-allow-origin' || echo "no ACAO header"; done
echo; echo "== Open Beauty Facts: perfumes"
curl -s -m 30 -A 'palate-search-lab/1.0' 'https://world.openbeautyfacts.org/category/perfumes.json?page_size=1' | head -c 300; echo
curl -s -m 30 -A 'palate-search-lab/1.0' 'https://world.openbeautyfacts.org/cgi/search.pl?search_terms=acqua+di+gio+profondo&search_simple=1&action=process&json=1&page_size=8&fields=product_name,brands,image_front_small_url,code,categories_tags' | head -c 1800; echo
echo "== OBF dump size"; curl -sI -m 20 https://static.openbeautyfacts.org/data/en.openbeautyfacts.org.products.csv | grep -i 'content-length\|HTTP/'
echo; echo "== Wikidata: perfume class"
curl -s -m 30 -A 'palate-search-lab/1.0' 'https://www.wikidata.org/w/api.php?action=wbsearchentities&format=json&language=en&type=item&limit=5&search=perfume' | head -c 700; echo
q='SELECT (COUNT(*) AS ?n) (SUM(IF(BOUND(?img),1,0)) AS ?withImg) WHERE { ?i wdt:P31/wdt:P279* wd:Q131746 . OPTIONAL{?i wdt:P18 ?img} }'
curl -s -m 70 -A 'palate-search-lab/1.0' -H 'Accept: application/sparql-results+json' --data-urlencode "query=$q" https://query.wikidata.org/sparql | head -c 500; echo
q='SELECT ?i ?iLabel ?sl WHERE { ?i wdt:P31/wdt:P279* wd:Q131746 . ?i wikibase:sitelinks ?sl . SERVICE wikibase:label { bd:serviceParam wikibase:language "en". } } ORDER BY DESC(?sl) LIMIT 15'
curl -s -m 70 -A 'palate-search-lab/1.0' -H 'Accept: application/sparql-results+json' --data-urlencode "query=$q" https://query.wikidata.org/sparql | python3 -c "import sys,json; [print(b['iLabel']['value'],b['sl']['value']) for b in json.load(sys.stdin)['results']['bindings']]"
echo; echo "== HF datasets"
for s in fragrantica perfume fragrance; do echo "-- $s"; curl -s -m 30 "https://huggingface.co/api/datasets?search=$s&limit=8" | python3 -c "import sys,json; [print(d['id'],d.get('downloads'),d.get('license') or d.get('tags',[])[:3]) for d in json.load(sys.stdin)]"; done
echo; echo "== EPA vehicles"
curl -s -m 120 -o /tmp/veh.zip https://www.fueleconomy.gov/feg/epadata/vehicles.csv.zip && unzip -p /tmp/veh.zip vehicles.csv | head -c 1500 | head -3; unzip -p /tmp/veh.zip vehicles.csv | grep -i 'taycan' | cut -d, -f1-3 | head -3; unzip -p /tmp/veh.zip vehicles.csv | wc -l
echo; echo "== NHTSA"; curl -s -m 30 'https://vpic.nhtsa.dot.gov/api/vehicles/GetModelsForMake/porsche?format=json' | head -c 400; echo
echo "== cocktaildb"; curl -s -m 30 'https://www.thecocktaildb.com/api/json/v1/1/search.php?s=old' | python3 -c "import sys,json; d=json.load(sys.stdin); print(len(d['drinks'] or []), [x['strDrink'] for x in d['drinks'] or []][:6])"
